async function api(path,body,method='POST'){const r=await fetch('/api/world/x-protocol'+path,{method:body===undefined?'GET':method,headers:{'Content-Type':'application/json'},...(path==='/control'?{signal:AbortSignal.timeout?.(10000)}:{}),...(body===undefined?{}:{body:JSON.stringify(body)})});const d=await r.json();if(!r.ok){if(r.status===403&&d.error?.includes('refugio'))location.assign('/juegos/?view=play');throw Error(d.error||'No se pudo completar la acción.');}return d;}
