async function sound(value=true){enabled=value;$('#sound').innerHTML=worldIcon(value?'volume':'muted');$('#sound').setAttribute('aria-label',value?'Silenciar sonido':'Activar sonido');$('#sound').title=value?'Silenciar sonido':'Activar sonido';$('#sound').setAttribute('aria-pressed',String(value));const video=$('#video');video.muted=!value;video.volume=1;if(value&&state?.cinematic)cinema.unlock();announcer.setEnabled(value);if(value){await announcer.unlock();context||=new (window.AudioContext||window.webkitAudioContext)();await context.resume();syncMusic();music.retry();}else{syncMusic();weatherAudio?.pause();weatherKind=null;}}
function fx(good=true){if(!enabled||context?.state!=='running')return;const at=context.currentTime;for(const [i,hz]of (good?[520,780,1040]:[185,140]).entries()){const o=context.createOscillator(),g=context.createGain();o.type=good?'sine':'triangle';o.frequency.value=hz;g.gain.setValueAtTime(.0001,at+i*.06);g.gain.exponentialRampToValueAtTime(.06,at+i*.06+.015);g.gain.exponentialRampToValueAtTime(.0001,at+i*.06+.22);o.connect(g);g.connect(context.destination);o.start(at+i*.06);o.stop(at+i*.06+.24);}}
function countdownTone(n){if(!enabled||context?.state!=='running')return;const at=context.currentTime,o=context.createOscillator(),g=context.createGain();o.type='sine';o.frequency.value=n?540:1040;g.gain.setValueAtTime(.0001,at);g.gain.exponentialRampToValueAtTime(.16,at+.012);g.gain.exponentialRampToValueAtTime(.0001,at+(n?.22:.5));o.connect(g);g.connect(context.destination);o.start(at);o.stop(at+(n?.24:.52));}
