document.addEventListener('pointerdown',e=>{const b=e.target.closest('[data-pulse]');if(b&&!b.disabled){e.preventDefault();act({type:'duel',kind:b.dataset.pulse});}});document.addEventListener('keydown',e=>{if(e.code!=='Space'||e.repeat||e.target.closest('input,textarea,select')||document.querySelector('dialog[open]'))return;const b=$('[data-pulse="balance"]');if(b&&!b.disabled){e.preventDefault();act({type:'duel',kind:b.dataset.pulse});}});let dragFrom=null;document.addEventListener('dragstart',e=>{const b=e.target.closest('[data-piece]');if(b){dragFrom=Number(b.dataset.piece);e.dataTransfer.setData('text/plain',String(dragFrom));}});document.addEventListener('dragover',e=>{if(e.target.closest('[data-piece]'))e.preventDefault();});document.addEventListener('drop',e=>{const b=e.target.closest('[data-piece]');if(b&&dragFrom!==null){e.preventDefault();const to=Number(b.dataset.piece);if(to!==dragFrom)act({type:'duel',kind:'swap',from:dragFrom,to});dragFrom=null;}});
$('#choose-results').onclick=()=>{const id=$('#results-select').value;if(id)act({type:'results',sourceId:id});else notice('Primero completa un reto o registra su ranking.');};$('#save-result').onclick=async()=>{try{const ids=$('#result-ranking').value.split(/[\n,]+/).map(x=>x.trim().toLowerCase()).filter(Boolean);if(ids.length!==state.capacity)throw Error('Incluye los '+state.capacity+' identificadores activos, uno por línea.');await api('/results',{name:$('#result-name').value,ranking:ids.map(characterId=>({characterId,name:WORLD_CHARACTERS.find(p=>p.id===characterId)?.name}))});await fetchResults();notice('Resultado guardado. Ya puedes seleccionarlo.');}catch(e){notice(e.message);}};
$('#result-ranking').value=SHELTER_PARTICIPANTS.join('\n');



function narrativeUI(){const s=state,mode=arenaMode(s);document.body.dataset.scene=mode;$('#arena-timer').hidden=!['BETTING_PHASE','WINNER_NOMINATION','GROUP_VOTE','TIEBREAKER_VOTE','LUCKY_SKULLS_PICKING','DUEL_ACTIVE'].includes(s.phase);$('#arena-timer').textContent=s.duel?.type==='balance'&&s.phase==='DUEL_ACTIVE'?(s.duel.roundEndAt?'RONDA PARA '+name(s.duel.roundWinner):'RONDA '+s.duel.round+' / 3'):Math.max(0,Math.ceil(((s.deadline||0)-s.clock)/1000))+' s';$('#arena-timer').classList.toggle('round-status',s.duel?.type==='balance'&&s.phase==='DUEL_ACTIVE');$('#skull-order').hidden=mode!=='skulls';if(mode==='skulls')$('#skull-order').innerHTML='<small>ORDEN DE ELECCIÓN</small>'+s.skulls.order.map((id,i)=>'<div class="'+(s.skulls.turn===i?'active':'')+'"><b>'+(i+1)+'</b>'+esc(name(id))+(Object.hasOwn(s.skulls.picks,id)?' ✓':'')+'</div>').join('');const split=$('#result-split'),show=mode==='result';split.hidden=!show;$('#host').hidden=show;$('#monitor>div:not(#result-split)').hidden=show;const special=show&&['double_elimination','double_save'].includes(s.duel.outcome);split.classList.toggle('special-result',special);if(special){const saved=s.duel.outcome==='double_save',key=s.id+':'+s.duel.outcome+':'+(s.duel.protected||[]).join(',');if(split.dataset.key!==key){split.dataset.key=key;const card=id=>'<div class="'+(saved||s.duel.protected?.includes(id)?'winner':'loser')+'"><img src="'+portrait(person(id))+'" alt=""><strong>'+esc(name(id))+'</strong><b>'+(saved||s.duel.protected?.includes(id)?'A SALVO':eliminatedLabel(person(id)))+'</b></div>';split.innerHTML=card(s.duel.ids[0])+'<div class="outcome-copy"><small>THE X PROTOCOL</small><strong>'+(saved?'AMBOS A SALVO':s.duel.protected?.length?'ELIMINACIÓN MODIFICADA':'DOBLE ELIMINACIÓN')+'</strong><p>'+esc(saved?DOUBLE_SAVE_TEXT:s.duel.protected?.length?'La ventaja ha protegido a '+s.duel.protected.map(name).join(' y ')+'. '+duelLosers(s.duel).map(name).join(' y ')+' abandona la competencia.':DOUBLE_LOSS_TEXT)+'</p></div>'+card(s.duel.ids[1]);}return;}if(show&&split.dataset.key!==s.id+':'+s.duel.winner){split.dataset.key=s.id+':'+s.duel.winner;split.innerHTML='<div class="winner"><img src="'+portrait(person(s.duel.winner))+'" alt=""><strong>'+esc(name(s.duel.winner))+'</strong><b>♛ '+duelWinnerLabel(person(s.duel.winner))+'</b></div><div class="presenter"><img src="art/poses/host-maria-v2-2.webp" alt="María Villegas"><small>MARÍA VILLEGAS</small><strong>THE <em>X</em> PROTOCOL</strong></div><div class="loser"><img src="'+portrait(person(s.duel.loser))+'" alt=""><strong>'+esc(name(s.duel.loser))+'</strong><b>☠ '+eliminatedLabel(person(s.duel.loser))+'</b></div>';}}

function renderVitals(){const v=state.ownVitals||{},defs=[['health','Salud'],['hunger','Hambre'],['energy','Energía'],['sleep','Sueño'],['stress','Estrés']];if(!$('#vitals').children.length)$('#vitals').innerHTML='<small>TU ESTADO</small>'+defs.map(([id,label])=>'<div class="vital" data-v="'+id+'"><span>'+label+'</span><i><b></b></i><strong></strong></div>').join('')+'<div class="impact"></div>';for(const [id]of defs){const root=$('#vitals [data-v='+id+']'),value=Math.round(v[id]??(id==='stress'?0:100));root.querySelector('b').style.width=value+'%';root.querySelector('strong').textContent=value;root.classList.toggle('critical',id==='stress'?value>75:value<25);}$('#vitals .impact').textContent='Influencia en el duelo: '+Math.round(state.ownPenalty*100)+'% · máximo 14%';}
function renderScores(){const d=state.duel,visible=d&&['DUEL_TYPE_REVEAL','BETTING_PHASE','DUEL_GUIDE','DUEL_COUNTDOWN','DUEL_ACTIVE','DUEL_RESULT'].includes(state.phase),root=$('#scoreboard');root.hidden=!visible;if(!visible)return;const key=state.id+':'+d.type+':'+d.ids.join();if(root.dataset.key!==key){root.dataset.key=key;root.innerHTML=d.ids.map(id=>'<div class="score-card" data-id="'+esc(id)+'"><img src="'+portrait(person(id))+'" alt=""><div><small>'+esc(DUELS[d.type].name)+'</small><strong>'+esc(name(id))+'</strong><div class="meter"><b></b></div></div><b class="metric"></b></div>').join('');}for(const [i,id]of d.ids.entries()){const a=d.actors[id],card=root.children[i],value=d.type==='typing'?a.score:d.type==='puzzle'?a.progress:d.type==='lights'?a.good:d.type==='balance'?a.balance:i?100-d.force:d.force,max=d.type==='typing'?TYPING_GOAL:d.type==='lights'?6:100;card.querySelector('small').textContent=d.type==='balance'?'RONDA '+d.round+' / 3 · '+(d.roundWins[id]||0)+' VICTORIAS':DUELS[d.type].name;card.querySelector('.metric').textContent=d.type==='puzzle'?(d.actors[id].completed||0)+'/3':d.type==='typing'?value+'/'+TYPING_GOAL:d.type==='lights'?value+'/6':value.toFixed(d.type==='rope'?1:0)+'%';card.querySelector('.meter b').style.width=Math.min(100,value/max*100)+'%';}}

async function connect(){try{boot=await fetch('/api/world/bootstrap').then(async r=>{const d=await r.json();if(!r.ok)throw Error(d.error||'Entra desde tu sesión de World.');return d;});const d=await api('');shopUI.update(boot.shop);update(d.episode);if(['CLOSED','LOBBY','ELIMINATION_FINISHED'].includes(state.phase)&&!historyUI.shown)void historyUI.open();for(const m of d.history||[])chat({...m,userId:m.sender});socket=new WebSocket(location.origin.replace(/^http/,'ws')+'/api/world/live?zone='+encodeURIComponent(boot.profile.lastZone));socket.onopen=()=>{connected=true;readySent=null;$('#connection').textContent='● EN VIVO';wire({type:'protocol-subscribe'});wire({type:'protocol-viewer',visible:!!state?.cinematic||!document.hidden});ensureEntryResources();};socket.onmessage=e=>{let m;try{m=JSON.parse(e.data);}catch{return;}historyUI.handle(m);shopUI.handle(m);if(m.type==='protocol-state')update(m.episode);if(m.type==='protocol-return')location.assign(m.url);if(m.type==='protocol-chat')chat(m.message);if(m.type==='protocol-announcement'){lastCommunication=m.message;announcer.preview(m.message);}if(m.type==='maria-voice')receiveVoice(m.announcement);if(m.type==='maria-voice-cancel')cancelVoice(m.announcement);if(m.type==='maria-voice-error')announcer.dismiss(m.id);for(const a of m.mariaVoice||[])receiveVoice(a);if(m.type==='error')notice(m.message);};socket.onclose=e=>{connected=false;$('#connection').textContent='RECONECTANDO';if(e.code===4002)return notice('Tu cuenta está abierta en otra pestaña de World. Usa una sola pestaña por cuenta.');if(!disposed)retryTimer=setTimeout(()=>void connect(),2500);};if(new URLSearchParams(location.search).has('staff-preview')&&state.staff)$('#direction').hidden=false;}catch(e){notice(e.message);$('#phase').textContent='Sesión no disponible';}}
window.addEventListener('pagehide',()=>{disposed=true;clearTimeout(retryTimer);clearTimeout(entryRetry);for(const pending of pendingProtocolVoices.values())clearTimeout(pending.timer);pendingProtocolVoices.clear();cancelAnimationFrame(frame);cinema.destroy();preparation.destroy();polish.destroy();historyUI.destroy();shopUI.destroy();announcer.destroy();music.destroy();weatherAudio?.pause();socket?.close();});
void renderer.load().then(()=>{if(disposed)return;if(state){void renderer.preloadDuel(state).catch(()=>{});if(state.phase==='INTRO_VIDEO')void renderer.preloadEntry(state).catch(()=>{});geometry();}loaded=true;$('#asset-loader').hidden=state?.phase!=='ELIMINATION_LOADING';ensureEntryResources();}).catch(()=>{if(disposed)return;notice('No se pudieron cargar algunas imágenes. Comprueba tu conexión.');loaded=true;$('#asset-loader').hidden=state?.phase!=='ELIMINATION_LOADING';ensureEntryResources();});void connect();frame=requestAnimationFrame(draw);
